/* Embedded restaurant branding and 20 food photos. No assets folder required. */
(()=>{const M={
"3sec-logo.webp":"data:image/webp;base64,",
"food-01.webp":"data:image/webp;base64,",
"food-02.webp":"data:image/webp;base64,",
"food-03.webp":"data:image/webp;base64,",
"food-04.webp":"data:image/webp;base64,",
"food-05.webp":"data:image/webp;base64,",
"food-06.webp":"data:image/webp;base64,",
"food-07.webp":"data:image/webp;base64,",
"food-08.webp":"data:image/webp;base64,",
"food-09.webp":"data:image/webp;base64,",
"food-10.webp":"data:image/webp;base64,",
"food-11.webp":"data:image/webp;base64,",
"food-12.webp":"data:image/webp;base64,",
"food-13.webp":"data:image/webp;base64,",
"food-14.webp":"data:image/webp;base64,",
"food-15.webp":"data:image/webp;base64,",
"food-16.webp":"data:image/webp;base64,",
"food-17.webp":"data:image/webp;base64,",
"food-18.webp":"data:image/webp;base64,",
"food-19.webp":"data:image/webp;base64,",
"food-20.webp":"data:image/webp;base64,",
};window.KITCHEN_IMAGES=M;document.querySelectorAll("video[data-poster]").forEach(v=>{const k=v.getAttribute("data-poster");if(M[k])v.poster=M[k]});document.querySelectorAll("[data-media]").forEach(el=>{let key=el.getAttribute("data-media");if(M[key]){if(el.tagName==="LINK")el.href=M[key];else el.src=M[key]}});})();